import * as T from './assets/three.module.js';
import {makeSatellite} from './spacefx.js';
import {satellitePosition,hasLineOfSight,circularPeriod} from './simulation-math.js';
export function makeStation(){
 const group=new T.Group(),silver=new T.MeshStandardMaterial({color:0xc9d4dc,roughness:.3,metalness:.72}),dark=new T.MeshStandardMaterial({color:0x314253,roughness:.5,metalness:.7}),solar=new T.MeshStandardMaterial({color:0x163457,emissive:0x08182f,roughness:.3,metalness:.6,side:T.DoubleSide});
 const part=(geo,mat,x=0,y=0,z=0)=>{const m=new T.Mesh(geo,mat);m.position.set(x,y,z);group.add(m);return m};
 part(new T.BoxGeometry(1.5,.035,.035),silver);for(let i=-2;i<=2;i++){const m=part(new T.CylinderGeometry(.085,.085,.28,24),silver,i*.16,0,0);m.rotation.z=Math.PI/2;part(new T.TorusGeometry(.087,.008,8,24),dark,i*.16,0,0).rotation.y=Math.PI/2;}
 for(const x of [-.62,-.32,.32,.62])for(const sign of [-1,1]){part(new T.BoxGeometry(.19,.012,.46),solar,x,0,sign*.32);for(let j=0;j<8;j++)part(new T.BoxGeometry(.191,.014,.002),dark,x,0,sign*.32-.2+j*.058);}
 const cupola=part(new T.SphereGeometry(.075,16,12),dark,0,.1,0);cupola.scale.y=.6;
 for(const sign of [-1,1]){part(new T.BoxGeometry(.2,.15,.13),silver,sign*.2,0,.16);part(new T.CylinderGeometry(.035,.035,.2,12),silver,sign*.2,0,.3).rotation.x=Math.PI/2;}
 group.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});return group;
}
export function setupOrbitalNetwork(stage,scene){
 const tools=document.createElement('details');tools.className='orbital-network-controls';tools.open=true;tools.innerHTML='<summary>Earth orbital network <span>STATIONS / RELAYS / GROUND LINKS</span></summary><div class="network-toolbar"><label><input id="network-stations" type="checkbox" checked> Stations & satellites</label><label><input id="network-links" type="checkbox" checked> Communication links</label><label><input id="network-orbits" type="checkbox" checked> Orbit paths</label><label><input id="network-coverage" type="checkbox"> Ground coverage</label><label>Track asset<select id="network-track"><option value="none">Free camera</option><option value="0">Aster station / concept</option><option value="1">Horizon station / concept</option><option value="2">Relay 01</option><option value="3">Relay 02</option><option value="4">Relay 03</option><option value="5">Surveyor 01</option></select></label><label>Orbital time<input id="network-speed" type="range" min="1" max="500" value="100"></label><button id="network-ping">Transmit packet ↗</button><output id="network-status">Concept constellation / not live tracking</output></div>';
 stage.closest('.hero-layout').after(tools);
 const $=id=>tools.querySelector(id),group=new T.Group(),orbitGroup=new T.Group(),assets=new T.Group(),links=new T.Group(),coverage=new T.Group();group.add(orbitGroup,assets,links,coverage);scene.add(group);
 const definitions=Array.from({length:8},(_,i)=>({alt:i<2?420:i<5?1500:700,inc:(i<2?51.6:i<5?35:97)*Math.PI/180,node:i*1.32,phase:i*1.9}));
 const objects=definitions.map((d,i)=>{const o=i<2?makeStation():makeSatellite();o.scale.setScalar(i<2?.11:.38);assets.add(o);const points=Array.from({length:161},(_,j)=>{const p=satellitePosition(j/160*Math.PI*2,1.46*(1+d.alt/6378.1),d.inc,d.node);return new T.Vector3(p.x,p.y,p.z)});orbitGroup.add(new T.Line(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:i<2?0xe1ba82:0x70a5c1,transparent:true,opacity:i<2?.25:.10,depthWrite:false})));return o;});
 const ground=[[29,-95],[-24,134],[40,-4]].map(([lat,lon])=>{const a=lat*Math.PI/180,b=lon*Math.PI/180,v=new T.Vector3(Math.cos(a)*Math.sin(b),Math.sin(a),Math.cos(a)*Math.cos(b)).multiplyScalar(1.464),m=new T.Mesh(new T.OctahedronGeometry(.015),new T.MeshBasicMaterial({color:0x8ae2d4}));m.position.copy(v);assets.add(m);const c=new T.Mesh(new T.ConeGeometry(.24,.4,48,1,true),new T.MeshBasicMaterial({color:0x65b4c8,transparent:true,opacity:.10,side:T.DoubleSide,depthWrite:false}));c.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),v.clone().normalize());c.position.copy(v).addScaledVector(v.clone().normalize(),.2);coverage.add(c);return m});
 const pairs=[];for(let i=0;i<objects.length;i++)for(let j=i+1;j<objects.length;j++)if(j-i<3)pairs.push([objects[i],objects[j]]);for(let i=0;i<ground.length;i++)pairs.push([ground[i],objects[i*2]]);
 const routes=pairs.map(([a,b])=>{const line=new T.Line(new T.BufferGeometry().setAttribute('position',new T.BufferAttribute(new Float32Array(6),3)),new T.LineBasicMaterial({color:0x78e4d4,transparent:true,opacity:.32,depthWrite:false}));links.add(line);const packet=new T.Mesh(new T.SphereGeometry(.008,8,6),new T.MeshBasicMaterial({color:0xe0fff5}));links.add(packet);return {a,b,line,packet}});
 let time=0,burst=0,ui=0;$('#network-ping').onclick=()=>{burst=3;$('#network-status').textContent='TRANSMITTING / unobstructed inter-satellite and ground links'};
 return {group,frame(dt,current,motion,enabled=true){group.visible=current===2&&enabled;if(!group.visible)return null;tools.hidden=current!==2;if(motion){time+=dt*+$('#network-speed').value;burst=Math.max(0,burst-dt)}assets.visible=$('#network-stations').checked;orbitGroup.visible=$('#network-orbits').checked;coverage.visible=$('#network-coverage').checked;links.visible=$('#network-links').checked&&assets.visible;objects.forEach((o,i)=>{const d=definitions[i],phase=d.phase+time/circularPeriod(d.alt)*Math.PI*2,p=satellitePosition(phase,1.46*(1+d.alt/6378.1),d.inc,d.node);o.position.set(p.x,p.y,p.z);o.lookAt(0,0,0);o.rotateZ(Math.PI/2)});let connected=0;routes.forEach((r,i)=>{const on=hasLineOfSight(r.a.position,r.b.position);r.line.visible=r.packet.visible=on;if(!on)return;connected++;const p=r.line.geometry.attributes.position;p.setXYZ(0,...r.a.position.toArray());p.setXYZ(1,...r.b.position.toArray());p.needsUpdate=true;r.line.material.opacity=burst>0?.65:.18;r.packet.position.lerpVectors(r.a.position,r.b.position,(time*.003+i*.19)%1)});ui+=dt;if(ui>.5){ui=0;$('#network-status').textContent=`${connected} clear links · Earth blocks occulted routes · orbital time ${$('#network-speed').value}× · enlarged concept assets`;}const track=$('#network-track').value;return track==='none'?null:objects[+track].position;},hide(current){tools.hidden=current!==2;group.visible=current===2;}};
}
